import{_ as n,o as i,c as t,a5 as h}from"./chunks/framework.CsGesDJn.js";const k=JSON.parse('{"title":"FR 3.5.6 — Client góp ý và Manager triển khai Campaign","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-6-approve-media-campaign/spec.md","filePath":"feature/media-package-campaign/3-5-6-approve-media-campaign/spec.md"}'),e={name:"feature/media-package-campaign/3-5-6-approve-media-campaign/spec.md"};function g(r,a,c,p,l,o){return i(),t("div",null,[...a[0]||(a[0]=[h('<h1 id="fr-3-5-6-—-client-gop-y-va-manager-trien-khai-campaign" tabindex="-1">FR 3.5.6 — Client góp ý và Manager triển khai Campaign <a class="header-anchor" href="#fr-3-5-6-—-client-gop-y-va-manager-trien-khai-campaign" aria-label="Permalink to &quot;FR 3.5.6 — Client góp ý và Manager triển khai Campaign&quot;">​</a></h1><p>Cập nhật BA 2026-11-05. Bước duyệt Campaign hai phía đã được thay bằng <a href="./../guest-sharing-manager-led/spec.html">flow xem/góp ý và Manager triển khai</a>.</p><h2 id="quyen-va-gop-y" tabindex="-1">Quyền và góp ý <a class="header-anchor" href="#quyen-va-gop-y" aria-label="Permalink to &quot;Quyền và góp ý&quot;">​</a></h2><ul><li>Client đã tham gia đúng workspace được xem Campaign DRAFT, IN_PROGRESS và COMPLETED theo quyền xem hiện hành.</li><li>Client được comment góp ý cả khi Campaign còn DRAFT. Lưu người gửi, thời điểm và ngữ cảnh phiên bản đang xem khi có.</li><li>Comment không sửa kế hoạch, không chuyển trạng thái hoặc tạo approval. Manager quyết định xử lý góp ý trong phạm vi trạng thái cho phép.</li><li>Client không có nút approve/reject Campaign hoặc triển khai. Manager không cần chờ Client đồng ý/góp ý xong để triển khai.</li><li>Duyệt kết quả Task/bài đăng tiếp tục theo module Task và không được thay bằng comment Campaign.</li></ul><h2 id="trien-khai" tabindex="-1">Triển khai <a class="header-anchor" href="#trien-khai" aria-label="Permalink to &quot;Triển khai&quot;">​</a></h2><ul><li>Manager chủ động triển khai khi gói, kế hoạch, task và thông tin bắt buộc đã hợp lệ/đồng bộ.</li><li>Không còn gate Campaign APPROVED hoặc timestamp duyệt hai phía trong flow mới.</li><li>Lượt triển khai cố định bản gói/kế hoạch được dùng và ngăn sửa đồng thời. Lỗi/gián đoạn cho phép retry trên cùng bản, không ghi đè task hoặc sinh task trùng.</li><li>Campaign chuyển IN_PROGRESS sau khi xác nhận đầy đủ công việc theo gói. Các task đã tồn tại từ khi lưu gói được giữ định danh và thông tin đã nhập.</li><li>Sau triển khai khóa gói/phạm vi kế hoạch. Thành viên bắt đầu công việc theo quyền Task hiện hành.</li><li>Hoàn thành Campaign vẫn do Manager thực hiện với điều kiện closure hiện hành. Request/Task chưa xử lý vẫn là điều kiện chặn theo spec riêng.</li></ul><h2 id="trang-thai-va-ux" tabindex="-1">Trạng thái và UX <a class="header-anchor" href="#trang-thai-va-ux" aria-label="Permalink to &quot;Trạng thái và UX&quot;">​</a></h2><p>Vòng đời nghiệp vụ đích là DRAFT → IN_PROGRESS → COMPLETED. Tiến trình deployment/retry được hiển thị riêng. Giao diện Client tập trung kế hoạch, tiến độ và góp ý, dùng vi/en, semantic light/dark, bàn phím/mobile và các trạng thái tải/lỗi/trống/thiếu quyền.</p><p>API, trạng thái APPROVED cũ và lịch sử review/approval cần kế hoạch tương thích riêng. Không tự chuyển/xóa dữ liệu trong giai đoạn chỉnh spec.</p>',9)])])}const s=n(e,[["render",g]]);export{k as __pageData,s as default};
